    googleMeetOAuthCallback: {
        parameters: {
            query: {
                /** @description Authorization code from Google (opaque to us). */
                code: string;
                /** @description HMAC-signed state token issued by the authorize endpoint. */
                state: string;
            };
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /**
             * @description Redirect to SPA with `?tab=integrations&status=<result>`. Two flavors:
             *       - `status=connected` — success (7-step tx completed, tokens persisted).
             *       - `status=cancelled` — user hit Cancel on Google's consent screen
             *         (Google `?error=access_denied`); INTEGRATION_CONNECT_CANCELED path,
             *         no tokens persisted, no audit row. Frontend renders neutral toast.
             */
            302: {
                headers: {
                    /** @description SPA redirect target with tab + status query params. */
                    Location?: string;
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description OAUTH_STATE_INVALID (bad HMAC / tampered) or OAUTH_STATE_EXPIRED (past 10-min TTL) */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorEnvelope"];
                };
            };
            /** @description OAUTH_STATE_MISMATCH (state binding failure) or OAUTH_MEMBERSHIP_REVOKED (owner demoted between authorize and callback) */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorEnvelope"];
                };
            };
            /** @description RATE_LIMIT_EXCEEDED (Retry-After header) — per (centerID, IP) 5/min bucket */
            429: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorEnvelope"];
                };
            };
            /** @description INTEGRATION_CONNECT_FAILED — Google code exchange failed, membership check errored, or tx rolled back */
            502: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorEnvelope"];
                };
            };
            /** @description OAUTH_NOT_CONFIGURED — server missing Google OAuth or state-signer configuration (parity with authorize) */
            503: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorEnvelope"];
                };
            };
        };
    };
